#!/bin/bash
# Mac test of our own Control Center's panel (1.8.0 P2): its layout (common/CCLayout.h, test-cclayout.c: every tile's place from Apple's grid
# sizes, the stand-ins, the panel's place under the bar, its motion, a detail page's height), then the sites in the code as built
# (statusbar/CCPanel.h and its glue in StatusBar.x): nothing hooked unless Control Center Style is Mac, the checked API table, the containment rule,
# the crash guard's target, the bar copies not dressed while ours shows.
set -e
cd "$(dirname "$0")"
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
clang -O2 -Wall -Wno-unused-function -framework CoreGraphics -o "$W/tcl" test-cclayout.c
"$W/tcl"
fails=0
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fails=1; fi; }
S=../statusbar/StatusBar.x
P=../statusbar/CCPanel.h
Q=../statusbar/CC18Shape.h
check "StatusBar.x includes the panel and starts it in %ctor (its API check on 15-17; the hooks only with Mac), and lets its debug triggers in" \
  "grep -q '^#include \"CCPanel.h\" ' $S && grep -q 'if (!DMCtorSkip(\"ccpanel\")) DMCCPanelInit();' $S && grep -q 'else if (\[cmd hasPrefix:@\"ccp_\"\]) DMCCPDebugTrigger(cmd);' $S"
check "  ... a change of the preference applies the style while running (once Control Center is closed)" \
  "grep -q '    DMCCPPrefsChanged();   // (Control Center Style' $S && grep -q 'if (DMControlCenterActive()) {   // (applied once Control Center has closed' $P && grep -qF 'dispatch_get_main_queue(), ^{ if (gCCPPending && gen == gCCPPendingGen) DMCCPApplyStyle(@\"Control Center closed\"); });' $P && grep -qF 'if (gCCPPending) dispatch_async(dispatch_get_main_queue(), ^{ DMCCPApplyStyle(@\"Control Center closed\"); });' $P"
check "the gate: Mac only where Control Center Style's rule gives Mac (common/CCStyle.h as SpringBoard reads it, CCStyleSB.h, included before the panel: \"mac\" stored, never the default (KT 3 Nov); false, the crash guard's, never set and anything else is iPadOS's or BigSurCenter's); nothing hooked otherwise" \
  "grep -q 'static BOOL DMCCPStyleIsMac(void) { return DMCCStyleChosenNow() == kMSBDCCStyleMac; }' $P && ! grep -q 'CFSTR(\"controlCenterStyle\")' $P && awk '/^#include \"CCStyleSB.h\" /{a=NR} /^#include \"CCPanel.h\" /{b=NR} END{exit !(a && b && a < b)}' $S && grep -q 'BOOL want = gCCPSupported && DMCCPStyleIsMac() && !DMCCPOtherCC();' $P && awk '/^static void DMCCPApplyStyle/{f=1} f&&/if \(!want\) \{ DMCCPGiveBack\(why\); return; \}/{a=1} f&&a&&/if \(!DMCCPInstallHooks\(\)\) \{ DMCCPSetWanted\(NO\); return; \}/{print \"ok\"; exit}' $P | grep -q ok"
check "  ... the rule's first look in SpringBoard reads this start's verdict: the check publishes it before the style is first asked (DMCCPanelInit), and the panel starts before Control Center Style in %ctor" \
  "awk '/^static void DMCCPanelInit/{f=1} f&&/DMCCPPublishVerdict\(gCCPSupported, reason, bad, gCCPCheckOptional\);/{a=1} f&&a&&/DMCCPApplyStyle\(@\"start\"\);/{print \"ok\"; exit}' $P | grep -q ok && awk '/^    if \(!DMCtorSkip\(\"ccpanel\"\)\) DMCCPanelInit\(\);/{c=NR} /^    if \(!DMCtorSkip\(\"ccstyle\"\)\) DMCCStyleInit\(\);/{d=NR} END{exit !(c && d && c < d)}' $S"
check "  ... the 15-17 panel never on 18 (18 is CC18Shape.h's: Apple's own grid re-shaped), and the verdict's reader takes 15-18 (after 18: never read, not supported)" \
  "grep -q 'if (major < 15 || major > 17) return;' $P && grep -q 'if (major < 15 || major > 18) { if (reason) \*reason = major > 18' ../common/CCMacCheck.h && grep -q 'if (\[NSProcessInfo processInfo\].operatingSystemVersion.majorVersion != 18) return;' $Q"
check "  ... never next to BigSurCenter (its panel lives in the same overlay)" \
  "grep -q 'static BOOL DMCCPOtherCC(void) { return objc_getClass(\"SCMainViewController\") != Nil; }' $P && grep -q 'DMCCPGiveBack(@\"BigSurCenter is loaded\");' $P && awk '/^static void DMCCPViewDidLoad/{f=1} f&&/DMCCPOtherCCNow\(\);/{a=1} f&&a&&/o_DMCCPViewDidLoad\(self, _cmd\);/{print \"ok\"; exit}' $P | grep -q ok && grep -q 'if (!gCCPOn || DMCCPOtherCCNow()) return;' $P"
check "the API table: all or nothing (a core row missing or of another shape: nothing hooked, the verdict for Settings), optional rows only take their part" \
  "grep -q 'gCCPSupported = bad.count == 0;' $P && grep -q 'DMCCPPublishVerdict(gCCPSupported, reason, bad, gCCPCheckOptional);' $P && grep -q 'if (!DMCCPHookPartHere(kDMCCPHooks\[i\].part)) continue;' $P && grep -q 'return part == kDMCCPCore || (part == kDMCCPPartJoin && gCCPHaveJoin) || (part == kDMCCPPartSensor && gCCPHaveSensor) || (part == kDMCCPPartSensorList && gCCPHaveSensorList);' $P && grep -q 'if (\*kDMCCPHooks\[i\].orig) continue;' $P"
check "  ... the hook points with the encodings read on 15.6.1, 16.7.7 and 17.5.1" \
  "grep -q '\"moduleCollectionViewController:didAddModuleContainerViewController:\", \"v32@0:8@16@24\"' $P && grep -q '\"_updatePresentationForTransitionState:withCompletionHander:\", \"v32@0:8@16@?24\"' $P && grep -q '\"compactModeFrameForContentModuleContainerViewController:\", kDMCCPRectType \"24@0:8@16\"' $P && grep -q '\"_dismissalTapGestureRecognizerShouldBegin:\", \"B24@0:8@16\"' $P"
check "containment (spike rule 1): a container's view moves into our panel, then its controller (UIKit adds a child only under the controller its view is in); one whose controller cannot move takes its view back to Apple's grid; the same order back when iPadOS's look returns (into Apple's layout view)" \
  "awk '/^static void DMCCPAdopt/{f=1} f&&/\[gCCPScroll insertSubview:cv atIndex:0\];/{a=1} f&&a&&/\[gCCPVC addChildViewController:containerVC\];/{b=1} f&&b&&/if \(containerVC.parentViewController != gCCPVC\) \{/{c=1} f&&c&&/\[home insertSubview:cv atIndex:at\]/{print \"ok\"; exit}' $P | grep -q ok && awk '/^static void DMCCPGiveBack\(NSString \*why\) \{/{f=1} f&&/\[home insertSubview:cv atIndex:\(NSUInteger\)at\];/{a=1} f&&a&&/\[grid addChildViewController:vc\]; \[vc didMoveToParentViewController:grid\];/{b=1} f&&b&&/if \(vc.parentViewController != grid\) \{/{c=1} f&&c&&/\[gCCPScroll addSubview:cv\];/{print \"ok\"; exit}' $P | grep -q ok && grep -q 'UIView \*home = DMCCGet(grid, @\"moduleCollectionView\");' $P && grep -q '(BOOL)shouldAutomaticallyForwardAppearanceMethods { return NO; }' $P"
check "an adopted container gets Apple's presented look (no transform, opaque) before our frame: Apple's last dismissal left it moved and transparent" \
  "grep -q '    DMCCPPresentedLook(cv, containerVC, keep);   // (before our layout sets its frame' $P && awk '/^static void DMCCPPresentedLook\(/{f=1} f&&/if \(!CGAffineTransformIsIdentity\(v.transform\)\) \{/{a=1} f&&a&&/v.transform = CGAffineTransformIdentity;/{b=1} f&&b&&/v.alpha = 1.0;/{print \"ok\"; exit} f&&/^}/{exit}' $P | grep -q ok"
check "Apple's grid and header stay (spike rule 2): only the backdrop is hidden (ours, of Apple's material, behind an expanded module), a touch outside the panel is Apple's" \
  "grep -q 'if (back && !back.hidden) { back.hidden = YES; gCCPHidBackdrop = back; }' $P && grep -q '    gCCPDim.alpha = expanded ? 1.0 : 0.0;' $P && grep -q 'return hit == self ? nil : hit;' $P && ! grep -q '_headerPocketView\" *)\\] setHidden' $P"
check "  ... the hooks are tried once (a second try would hook our own functions again: a loop); one that did not go in turns the check's verdict off" \
  "grep -q 'if (!gCCPSupported || tried) return NO;' $P && grep -qF 'a system method our Control Center uses did not take its hook' $P"
check "an expansion still counted at the close is reset (else the panel would stay faded and take no touch); our tiles and swipe wait for Apple's blocking gestures, the content's pan too" \
  "awk '/^static void DMCCPDidDismissHook\(id self, SEL _cmd\) \{/{f=1} f&&/if \(gCCPExpanded\) \{/{a=1} f&&a&&/gCCPExpanded = nil; DMCCPExpandedLookSet\(NO\);/{print \"ok\"; exit} f&&/^}/{exit}' $P | grep -q ok && grep -q 'if (g == self.panGestureRecognizer && \[gCCPBlocking containsObject:other\]) return YES;' $P && grep -q 'gCCPScroll = \[DMCCPScrollView new\];' $P"
check "Apple's adds of one pass are laid out once (not per module); a tile without an identifier or a view is not taken" \
  "awk '/^static void DMCCPDidAdd/{f=1} f&&/DMCCPLayoutSoon\(\);/{print \"ok\"; exit}' $P | grep -q ok && ! grep -q 'DMCCPLayout(@\"a module added\")' $P && grep -q 'a tile without an identifier or a view: not added' $P"
check "the layout from CCLayout.h with Apple's own sizes and pitch (its grid rects, CCUILayoutOptions), never Auto Layout" \
  "grep -q 'MSBDCCResult r = MSBDCCLayout(items, k, gCCPMetrics);' $P && grep -q 'CGRect pf = DMCCPFrame(r.width, r.contentHeight);' $P && grep -q 'return MSBDCCPanelFrameUnder(screen.width, screen.height, DMMenuBarHeight(), width, contentH, DMCCPRTL(), s.origin.x, s.origin.y, s.size.width, s.size.height);' $P && grep -q 'MSBDCCMotion(progress, MSBReduceMotion(), &alpha, &dy);' $P && ! grep -q 'NSLayoutConstraint\|UIStackView\|UICollectionView' $P"
check "the user's order: Apple's own list, read at each layout and each presentation (a reorder in Settings while running moves no container)" \
  "grep -q '^    DMCCPSyncOrder();$' $P && grep -q 'BOOL reordered = DMCCPSyncOrder();' $P && grep -qF 'NSSelectorFromString(@\"sortModuleIdentifiers:forInterfaceOrientation:\"), [gCCPOrder copy], (long long)UIInterfaceOrientationPortrait);' $P && grep -qF '{ kDMCCPGrid, \"_settingsManager\", NULL, NO, YES, YES,' $P && grep -qF 'BOOL resized = !reordered && ![DMCCPSizesNow() isEqualToString:gCCPLaidSizes ?: @\"\"];' $P"
check "expanded views grow out of our tiles (a stand-in's out of its Mac tile), and our tiles open Apple's expanded views through -expandModule" \
  "grep -q 'return \[gCCPScroll convertRect:f.CGRectValue toView:to\];' $P && grep -q 'cv.hidden = items\[i\].hidden;' $P && grep -q 'NSSelectorFromString(@\"expandModule\")' $P"
check "dismissal: opaque hit-testing with no fill (the render server routes by it; a 2 % fill cost every opening long frames); a swipe up on the panel handed to Apple's own pan, after the modules' blocking gestures" \
  "grep -q 'gCCPHost.backgroundColor = \[UIColor clearColor\];' $P && grep -q 'NSSelectorFromString(@\"setHitTestsAsOpaque:\")' $P && grep -q 'NSSelectorFromString(@\"_handleDismissalPanGestureRecognizer:\"), g);' $P && grep -q 'if (\[gCCPBlocking containsObject:other\]) return YES;' $P"
check "the motion joins Apple's own spring (its batch), else a short one of ours" \
  "grep -q 'NSSelectorFromString(@\"_baseC2AnimationParametersForTransitionState:\"), state)' $P && grep -q 'NSSelectorFromString(@\"addAnimation:\"), anim);' $P && grep -q 'if (!ours || gCCPJoined) return;' $P"
check "Control Center's own bar copies are not dressed as our menu bar while ours shows (15-17)" \
  "grep -q 'if (os >= 15 && os <= 17) return DMCCPanelOwnsCCBars() && fg.window && \[NSStringFromClass(\[fg.window class\]) isEqualToString:@\"SBControlCenterWindow\"\];' $S"
check "the crash guard: a crash in our Control Center sets the style back to iPadOS's (the false it writes is iPadOS's), with its own words" \
  "grep -q '^target controlcenter pref com.besiktasliseba.macstatusbar controlCenterStyle 0 1 Control Center Style|our Control Center$' crashmap-rules.txt && grep -q '^sym MacStatusBarCore ^_\*DMCCP\[A-Z\] controlcenter$' crashmap-rules.txt && grep -qxF 'file MacStatusBarCore ^(CCPanel|CCLayout|CCGiveBack)\\.h\$ controlcenter' crashmap-rules.txt && grep -q 'MSBDStepIsStockCC(f) ? @\"iPadOS.s Control Center is used for now\"' ../common/CrashExplain.h"
check "  ... also under the shared Control Center lookups (transparent: their caller decides, as under P4's trap in Apple's +sharedInstance), and in its layout (CCLayout.h: not all inlined in a release build)" \
  "grep -qxF 'sym MacStatusBarCore ^_?(MSBDControlCenterController|DMControlCenterController|DMControlCenterActive|DMCCTypes|DMCCGet|DMCCIvarOf)\$ transparent' crashmap-rules.txt && grep -q '^static inline id MSBDControlCenterController(void) {' ../common/CCController.h && grep -q '^static id DMControlCenterController(void) { return MSBDControlCenterController(); }' $S && grep -q '^static BOOL DMControlCenterActive(void) {' $S && grep -q '^static id DMCCGet(id target, NSString \*sel) {' $S && grep -q '^static BOOL DMCCTypes(id target, NSString \*sel, const char \*types) {' $S && grep -q '^static id DMCCIvarOf(id obj, const char \*name, const char \*type) {' $S"
check "  ... and the lookups' other callers keep targets that stop them: the tick is the Mac status bar's (not the engine notice's section), RAM & CPU's add's hooks and rules the part (Stock status bar mode keeps them)" \
  "grep -qxF 'sym MacStatusBarCore ^_*DMTick(Body)?(_block_invoke(_[0-9]+)?(\\.[0-9]+)?)?\$ stock' crashmap-rules.txt && grep -qxF 'sym MacStatusBarCore \\\$CCAutoAddWatch\\\$ part' crashmap-rules.txt && grep -qxF 'file MacStatusBarCore ^CCAutoAdd\\.h\$ part' crashmap-rules.txt && grep -q '^%group CCAutoAddWatch$' $S && grep -q '^static void DMTickBody(void) {' $S"
check "  ... every C function of the panel is named DMCCP (the sym rule also catches what is inlined elsewhere)" \
  "! grep -E '^(__attribute__\(\(unused\)\) )?static [A-Za-z_<> *]+[ *]([A-Za-z_]+)\(' $P | grep -v -E '[ *](DMCCP[A-Za-z]*)\(' | grep -q ."
check "the verdict's reader for Settings (P1) and the diagnostics' record" \
  "grep -q '#define MSBD_CC_CHECK_KEY CFSTR(\"controlCenterMacCheck\")' ../common/CCMacCheck.h && grep -q '@\"Finder\", @\"ControlCenter\"\]' ../common/Diag.h && grep -q 'MSBDDiagWrite(@\"ControlCenter\",' $P"
check "P4: Esc on a hardware keyboard closes our Control Center (an open page goes back first), from SpringBoard's always-installed press hook (Control Center's window has the keys while it shows: 16.7.7, 15.6.1), after the Downloads panel and our menus" \
  "grep -q '    if (!gOverlay && DMCCPanelEscape(presses)) return;' $S && awk '/^static BOOL DMCCPanelEscape/{f=1} f&&/if \(!gCCPOn \|\| !gCCPHost.window \|\| !DMControlCenterActive\(\)\) return NO;/{a=1} f&&a&&/if \(gCCPDetail\) DMCCPanelCloseDetail\(YES\); else DMCCPanelDismiss\(\);/{print \"ok\"; exit}' $P | grep -q ok"
check "P4: the menu bar's Control Center icon shows with Battery Menu off while ours is the style (KT 3 Nov); the bar is laid out again when that changes" \
  "grep -q '    DMCCPSetWanted(want);' $P && awk '/^static void DMCCPSetWanted/{f=1} f&&/for \(UIView \*fg in gCopies.allObjects\) \[fg setNeedsLayout\];/{print \"ok\"; exit}' $P | grep -q ok && grep -qF 'static BOOL DMCCPanelWanted(void) { return gCCPWant || DMCC18PanelWanted(); }' $P"
check "P4: CCAutoAdd and the label walks know our panel: room by the panel's own rules (Apple's grid under it is empty), our tiles' and pages' text never read as a module's" \
  "grep -q '    if (DMCCPanelOn()) {   // (our own Control Center shows' $S && grep -qF 'if (DMCCPanelOn()) DMCC_UNTOLD(@\"our own Control Center shows: Apple' $S && grep -q '                if (DMCCPanelOwnView(v)) continue;' $S && grep -q 'MSBDCCRoomForOneAt(items, k, extra, gCCPMetrics, gCCPSize, MIN(sz.width, sz.height), DMMenuBarHeight(), &need, &roomH, NULL);' $P"
check "P4: Apple's sensor indicator (camera, microphone, location in use) shows over the panel: the panel hangs under it (read at the first presentation step and when Apple updates it), the header's copy of the status icons stays at alpha 0, Apple's list of the apps steps the panel back -- each an optional part" \
  "grep -qF '{ kDMCCPOverlay, \"_updateSensorActivityStatusForHeaderPocketView\", \"v16@0:8\", (void *)DMCCPSensorUpdate, (void **)&o_DMCCPSensorUpdate, kDMCCPPartSensor,' $P && grep -qF '{ \"CCUIHeaderPocketView\", \"setStatusBarAlpha:\", \"v24@0:8d16\", (void *)DMCCPHeaderBarAlpha, (void **)&o_DMCCPHeaderBarAlpha, kDMCCPPartSensor,' $P && grep -qF '{ kDMCCPOverlay, \"willOpenExpandedSensorAttributionViewController\", \"v16@0:8\", (void *)DMCCPSensorListOpen, (void **)&o_DMCCPSensorListOpen, kDMCCPPartSensorList,' $P && grep -q 'if (ours && gCCPSensorDue) { gCCPSensorDue = NO; DMCCPSensorLook(@\"Control Center presenting\", NO); }' $P && grep -q 'BOOL ours = gCCPOn && ((UIView \*)gCCPHost).superview;   // (our host' $P && grep -q 'o_DMCCPHeaderBarAlpha(self, _cmd, ours ? 0.0 : a);' $P && grep -q 'if (r && gCCPOn && p.window && !gCCPExpanded && !gCCPSensorList &&' $P"
check "P4: the tiles' first reads are done once while the panel is hidden (the settle after Apple's build), so the first pull after a start does not pay them" \
  "awk '/^static void DMCCPSettleSoon/{f=1} f&&/if \(!warmed && hidden\) \{/{a=1} f&&a&&/if \(\[\(id\)t respondsToSelector:@selector\(tileWillPresent\)\]\) \[t tileWillPresent\];/{print \"ok\"; exit}' $P | grep -q ok"
check "P4: the indicator's parts: the list's rows go in only with the room's (gCCPHaveSensorList needs gCCPHaveSensor); the look at each presentation's first step, laid out without an animation; Apple's updates looked at only while Control Center shows; the header's bar copy held at 0 from the presentation's start" \
  "grep -qF '{ kDMCCPOverlay, \"didCloseExpandedSensorAttributionViewController\", \"v16@0:8\", (void *)DMCCPSensorListClose, (void **)&o_DMCCPSensorListClose, kDMCCPPartSensorList,' $P && grep -q 'gCCPHaveSensor = sensor; gCCPHaveSensorList = sensorList && sensor;' $P && awk '/^static void DMCCPWillPresent\(void\) \{/{f=1} f&&/DMCCPHeaderBarAway\(\);/{a=1} f&&a&&/gCCPSensorDue = gCCPHaveSensor;/{print \"ok\"; exit} f&&/^}/{exit}' $P | grep -q ok && grep -q 'DMCCPSensorLook(@\"Control Center presenting\", NO); }' $P && grep -q 'else \[UIView performWithoutAnimation:^{ DMCCPLayout(why); }\];' $P && grep -q 'if (!gCCPOn || self != gCCPOverlay || !gCCPShown) return;   // (closed: the next presentation' $P"
check "P4: the indicator's state reset when Control Center closes (the list's flag, the panel's alpha) and when iPadOS's look comes back (the indicator's place too); a list closed while Control Center goes away leaves the panel out" \
  "awk '/^static void DMCCPDidDismissHook\\(id self, SEL _cmd\\) \\{/{f=1} f&&/gCCPSensorList = NO;/{a=1} f&&a&&/if \(gCCPPanel.alpha != 1.0\) gCCPPanel.alpha = 1.0;/{print \"ok\"; exit} f&&/^}/{exit}' $P | grep -q ok && grep -q 'gCCPSensorList = NO; gCCPPanel.alpha = 1.0; gCCPSensor = CGRectZero;' $P && grep -q 'if (st == 0 || st == 3) { gCCPSensorList = NO; return; }' $P"
check "P4: every panel frame goes through DMCCPFrame (under the indicator): no other MSBDCCPanelFrame call in the panel" \
  "[ \$(grep -c 'MSBDCCPanelFrame' $P) = 1 ] && grep -q 'return MSBDCCPanelFrameUnder(' $P"
check "P4: Esc in SpringBoard's press hook after the Downloads panel and our menus, Esc alone (no Command, Control, Option or Shift)" \
  "awk '/^static void DMOverlayPressesBegan/{f=1} f&&/if \(DMDownloadsPanelTakesEsc\(presses\)\) return;/{a=NR} f&&/if \(gOverlay\) for \(UIPress \*p in presses\)/{b=NR} f&&/if \(!gOverlay && DMCCPanelEscape\(presses\)\) return;/{c=NR} f&&/^}/{exit} END{exit !(a && b && c && a<b && b<c)}' $S && grep -q '(p.key.modifierFlags & (UIKeyModifierCommand | UIKeyModifierControl | UIKeyModifierAlternate | UIKeyModifierShift))) continue;' $P"
check "P4: our own views for the label walks: the page, our backdrop, our material and every tile's view (Apple's adopted containers are walked)" \
  "awk '/^static BOOL DMCCPanelOwnView/{f=1} f&&/if \(v == gCCPDetail \|\| v == gCCPDim \|\| v == gCCPMaterial\) return YES;/{a=1} f&&a&&/for \(id<DMCCTile> t in gCCPTiles\) if \(\[t tileView\] == v\) return YES;/{print \"ok\"; exit}' $P | grep -q ok"
check "P4: accessibility: a page takes VoiceOver to its back row and back to its tile (not after Control Center closed), the tiles under it no one's; RAM & CPU's tile and our numbers over Memory Magic's one element each (a double tap: what a tap does); the sliders' chevrons named" \
  "grep -q '    DMCCPAXMoveTo(back, YES);' $P && grep -q 'DMCCPAXMoveTo(animated ? \[tile tileView\] : nil, NO);' $P && awk '/^static void DMCCPAXMoveTo/{f=1} f&&/gCCPScroll.accessibilityElementsHidden = pageOpen;/{a=1} f&&a&&/gCCPScroll.userInteractionEnabled = !pageOpen;/{print \"ok\"; exit}' $P | grep -q ok && grep -q 'self.accessibilityLabel = @\"RAM and CPU\";' $S && grep -q 'if (!\[self dm_offers\]) return NO; DMOfferRAMCPU(); return YES;' $S && grep -q '_compact.isAccessibilityElement = YES;' ../ccmodule/MSBDRAMCPUModule.m && grep -q '_compact.accessibilityValue = _haveMem' ../ccmodule/MSBDRAMCPUModule.m && grep -q '_chevron.accessibilityLabel = \[_title.text stringByAppendingString:@\" Details\"\];' ../statusbar/CCTiles.h"
check "P4: our hooks of Apple's views never ask Control Center's controller (Apple calls them inside -[SBControlCenterController init]: +sharedInstance re-entered its dispatch_once and SpringBoard trapped at its start, 1.8.0~i11): they read gCCPShown, set by the controller's own -_willPresent / -_didDismiss" \
  "! awk '/^static void DMCCPSensorUpdate\\(id self/{f=1} f&&/DMControlCenterActive|DMControlCenterController/{print \"bad\"} f&&/^}/{f=0}' $P | grep -q bad && ! awk '/^- \\(void\\)layoutSubviews \\{   \\/\\/ \\(a turn/{f=1} f&&/DMControlCenterActive|DMControlCenterController/{print \"bad\"} f&&/^}/{f=0}' $P | grep -q bad && awk '/^static void DMCCPWillPresentHook\\(id self/{f=1} f&&/gCCPShown = YES;/{print \"ok\"; exit}' $P | grep -q ok && awk '/^static void DMCCPDidDismissHook\\(id self, SEL _cmd\\) \\{/{f=1} f&&/gCCPShown = NO;/{print \"ok\"; exit}' $P | grep -q ok"
check "release builds: the feature marker in the panel's own path, the test switches and triggers debug-only" \
  "grep -q 'DM_FEATURE_MARK(\"cc-mac\");' $P && ! awk '/^#if DEBUG/{d=1} /^#endif/{d=0} /DMTestFlag\(\"\/tmp\// && !d{print \"bad\"}' $P | grep -q bad"
# ---- iPadOS 18 (CC18Shape.h, 1.8.0 P5b: Apple's own 18 grid re-shaped into the Mac panel) ----
check "18: StatusBar.x includes CC18Shape.h after the panel and its tiles, starts it in %ctor after the 15-17 panel and before Control Center Style (its verdict is published before the style is first asked), follows our settings, lets its debug triggers in" \
  "awk '/^#include \"CCTiles.h\" /{a=NR} /^#include \"CC18Shape.h\" /{b=NR} END{exit !(a && b && a < b)}' $S && awk '/^    if \(!DMCtorSkip\(\"ccpanel\"\)\) DMCCPanelInit\(\);/{a=NR} /^    if \(!DMCtorSkip\(\"cc18\"\)\) DMCC18Init\(\);/{b=NR} /^    if \(!DMCtorSkip\(\"ccstyle\"\)\) DMCCStyleInit\(\);/{c=NR} END{exit !(a && b && c && a < b && b < c)}' $S && grep -q '^    DMCC18PrefsChanged();  // ' $S && grep -qF 'static void DMCC18Init(void) {' $Q && grep -qF 'static void DMCC18PrefsChanged(void) { if (gCC18Supported) DMCC18ApplyStyle(@\"the preference changed\"); }' $Q && grep -q 'else if (\[cmd hasPrefix:@\"c18m_\"\]) DMCC18DebugTrigger(cmd);' $S && awk '/else if \(\[cmd hasPrefix:@\"c18m_\"\]\)/{print (d ? \"ok\" : \"bad\"); exit} /^#if DEBUG/{d=1} /^#endif/{d=0}' $S | grep -q ok"
check "18: the gate -- Mac only where Control Center Style's rule gives Mac (DMCCStyleChosenNow, as the 15-17 panel) and no other Control Center is loaded (CCPanel.h's DMCCPOtherCC, as 15-17: review 11); the hooks go in only when Mac is chosen, once; the check runs on 18 only" \
  "grep -qF 'BOOL want = gCC18Supported && DMCCStyleChosenNow() == kMSBDCCStyleMac && !DMCCPOtherCC();' $Q && grep -qF 'BOOL want = gCCPSupported && DMCCPStyleIsMac() && !DMCCPOtherCC();' $P && grep -qF 'if (want && !DMCC18InstallHooks()) { DMCC18SetWanted(NO); return; }' $Q && grep -qF 'if (!gCC18Supported || tried) return NO;' $Q && ! grep -q 'CFSTR(\"controlCenterStyle\")' $Q"
check "18: the API table, all or nothing (a row missing or of another shape: nothing hooked, the verdict for Settings in CCMacCheck.h's record), a hook that did not go in turns the verdict off" \
